using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Markup;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using PeerChatDesktop;
class EmojiFeatureTest {
    static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    static readonly string[] Corpus={"😀","👩🏽‍💻","👨‍👩‍👧‍👦","🇺🇸","🇨🇦","1️⃣","❤️","🏳️‍🌈","🏴\U000E0067\U000E0062\U000E0065\U000E006E\U000E0067\U000E007F","e\u0301"};
    static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
    static void SaveImage(FrameworkElement element,string path){var bmp=new RenderTargetBitmap((int)element.ActualWidth,(int)element.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(element);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(path))png.Save(file);}
    static void RunPicker(EmojiPicker picker,Action action){var frame=new DispatcherFrame();picker.Closed+=(s,e)=>frame.Continue=false;picker.Show();picker.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,action);Dispatcher.PushFrame(frame);}
    [STAThread] static int Main(string[] args){try{var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        foreach(string s in Corpus){Check(EmojiEditing.Boundaries(s).SequenceEqual(new[]{0,s.Length}),"split sequence");Check(new UTF8Encoding(false,true).GetString(new UTF8Encoding(false,true).GetBytes(s))==s,"UTF8 round trip");var box=new TextBox{Text="a"+s+"b"};var editHost=new Window{Content=box,Width=300,Height=100,ShowInTaskbar=false};editHost.Show();editHost.UpdateLayout();box.Focus();box.IsUndoEnabled=false;box.IsUndoEnabled=true;box.Select(1+s.Length,0);Check(EmojiComposer.Delete(box,true)&&box.Text=="ab","backspace whole cluster");box.Undo();Check(box.Text=="a"+s+"b","undo cluster delete");EmojiComposer.Insert(box,"👍",2,1);Check(box.Text=="a👍b","selected interior expands safely");box.Undo();Check(box.Text=="a"+s+"b","undo insertion");editHost.Close();}
        Check(EmojiEditing.Boundaries("🇺🇸🇨🇦🇯🇵").Length==4,"flag pairing");
        Check(EmojiCatalog.Search("programmer","People").Count()==2&&EmojiCatalog.Search("LOL",null).Count()==2&&EmojiCatalog.Search("nonexistent123",null).Count()==0,"search/category");
        foreach(var e in EmojiCatalog.All)foreach(int t in Enumerable.Range(0,e.SkinTone?6:1))Check(EmojiEditing.Boundaries(e.Variant(t)).Length==2,"catalog variant cluster");
        Check(EmojiCatalog.All.First(e=>e.Text=="✌️").Variant(1)=="✌🏻","BMP tone standard sequence");
        var usage=new EmojiUsage(root,"fixture");usage.Used("👩🏽‍💻");usage.Used("😀");usage.Used("👩🏽‍💻");var reopened=new EmojiUsage(root,"fixture");Check(reopened.Recent[0]=="👩🏽‍💻"&&reopened.Counts["👩🏽‍💻"]==2,"protected persistence/frequency");Check(new EmojiUsage(root,"other-profile").Recent.Count==0,"profile binding");Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(root,"emoji-usage.v1"))).Contains("👩🏽‍💻"),"preferences plaintext");
        Window window;using(var stream=typeof(CoreAdapter).Assembly.GetManifestResourceStream("Main.xaml"))window=(Window)XamlReader.Load(stream);window.Show();var composer=(TextBox)window.FindName("Composer");composer.IsEnabled=true;composer.Text="";window.UpdateLayout();double empty=composer.ActualHeight;Console.WriteLine("COMPOSER empty="+empty+" min="+composer.MinHeight+" padding="+composer.Padding);Check(empty<=50&&empty>=42,"compact empty composer");composer.Text="a\nb\nc\nd\ne";window.UpdateLayout();Check(composer.ActualHeight>empty&&composer.ActualHeight<=150,"bounded multiline growth");Check(((TextBlock)window.FindName("ComposerHint")).VerticalAlignment==VerticalAlignment.Center&&composer.VerticalContentAlignment==VerticalAlignment.Center,"caret/placeholder alignment");
        composer.Text="before after";composer.IsUndoEnabled=false;composer.IsUndoEnabled=true;composer.Select(7,5);int insertion=7,selectedLength=5;string composed="before ";var picker=new EmojiPicker(window,reopened);picker.Insert=text=>{EmojiComposer.Insert(composer,text,insertion,selectedLength);insertion=composer.CaretIndex;selectedLength=0;composed+=text;return true;};
        RunPicker(picker,()=>{var search=(TextBox)Field(picker,"search");search.Text="programmer";picker.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(picker),0,Key.Down){RoutedEvent=Keyboard.PreviewKeyDownEvent});Check(picker.EntryButtons.First().IsKeyboardFocusWithin,"keyboard search to results");Check(picker.EntryButtons.Count()==2,"live search");((ComboBox)Field(picker,"tone")).SelectedIndex=3;var button=picker.EntryButtons.First();Check(((string)button.Tag).Contains("🏽")&&button.Content is Image,"colored skin tone");
            var star=((Grid)button.Parent).Children.OfType<Button>().Last();int recentCount=reopened.Recent.Count;int caret=composer.CaretIndex;star.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(picker.IsVisible&&composer.CaretIndex==caret&&reopened.Recent.Count==recentCount&&reopened.Favorites.Contains((string)button.Tag),"star without insert/close/caret movement");Check(search.Text=="programmer"&&((ComboBox)Field(picker,"category")).SelectedItem.ToString()=="All","star keeps navigation");
            for(int n=0;n<100;n++){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(picker.IsVisible&&search.Text=="programmer"&&composer.CaretIndex==composed.Length,"consecutive exact insertion without closing/reset");}Check(composer.Text==composed,"multi insertion exact content");string all=composer.Text;composer.Undo();Check(composer.Text!=all,"undo multiple selections");composer.Redo();Check(composer.Text==all,"redo exact sequences");
            picker.UpdateLayout();SaveImage(picker,Path.Combine(root,"emoji-picker.png"));picker.Close();});Check(picker.Selection.Contains("🏽"),"picker selection");Check(new EmojiUsage(root,"fixture").Favorites.SetEquals(reopened.Favorites),"favorites restart");Check(new EmojiUsage(root,"other-profile").Favorites.Count==0,"favorites profile isolation");
        composer.Text="hello world";composer.IsUndoEnabled=false;composer.IsUndoEnabled=true;composer.Select(6,5);EmojiComposer.Insert(composer,"😀",6,5);Check(composer.Text=="hello 😀"&&composer.CaretIndex==8,"ordinary selection caret insertion");composer.Undo();Check(composer.Text=="hello world","ordinary selection undo");composer.Redo();Check(composer.Text=="hello 😀","emoji redo");composer.Select(6,0);Check(EmojiComposer.Delete(composer,false)&&composer.Text=="hello ","forward delete emoji");
        var cancelled=new EmojiPicker(window,reopened);RunPicker(cancelled,()=>{Check(((TextBox)Field(cancelled,"search")).IsKeyboardFocusWithin,"initial focus");cancelled.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(cancelled),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});});Check(cancelled.Selection==null,"escape no insertion");
        var overview=new EmojiPicker(window,reopened);RunPicker(overview,()=>{overview.UpdateLayout();SaveImage(overview,Path.Combine(root,"emoji-overview.png"));var scroll=(ScrollViewer)Field(overview,"scroll");scroll.ScrollToVerticalOffset(80);scroll.UpdateLayout();double offset=scroll.VerticalOffset;var firstStar=((Grid)overview.EntryButtons.Last().Parent).Children.OfType<Button>().Last();firstStar.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(scroll.VerticalOffset==offset&&((ComboBox)Field(overview,"category")).SelectedItem.ToString()=="All","star retains scroll/category");firstStar.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var categories=(ComboBox)Field(overview,"category");Check(categories.Items[1].ToString()=="Favorites","favorites near beginning");categories.SelectedItem="Recent";Check(overview.EntryButtons.Count()==2,"recent picker");categories.SelectedItem="Frequent";Check((string)overview.EntryButtons.First().Tag=="👩🏽‍💻","frequent ordering");categories.SelectedItem="Favorites";Check(overview.EntryButtons.Count()==1,"favorites independent list");var star=((Grid)overview.EntryButtons.First().Parent).Children.OfType<Button>().Last();star.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(overview.IsVisible&&overview.EntryButtons.Count()==0&&new EmojiUsage(root,"fixture").Favorites.Count==0,"unstar persists without insertion/closing");overview.Close();});
        var outside=new EmojiPicker(window,reopened);RunPicker(outside,()=>{window.Activate();});Check(!outside.IsVisible&&outside.Selection==null,"outside activation dismisses");
        foreach(var entry in EmojiCatalog.All)foreach(int t in Enumerable.Range(0,entry.SkinTone?6:1)){var bitmap=EmojiColor.Get(entry.Variant(t));Check(bitmap!=null&&bitmap.IsFrozen,"catalog color coverage/frozen cache: "+entry.Name);}
        Check(EmojiColor.CachedCount<=128,"bounded decoded image cache");var face=EmojiColor.Get("😀");var pixels=new byte[face.PixelHeight*face.PixelWidth*4];face.CopyPixels(pixels,face.PixelWidth*4,0);Check(Enumerable.Range(0,pixels.Length/4).Any(i=>pixels[i*4+3]>0&&(pixels[i*4]!=pixels[i*4+1]||pixels[i*4+1]!=pixels[i*4+2])),"actual color pixels");var family=EmojiColor.Get("👨‍👩‍👧‍👦");var familyPixels=new byte[family.PixelHeight*family.PixelWidth*4];family.CopyPixels(familyPixels,family.PixelWidth*4,0);Check(Enumerable.Range(0,familyPixels.Length/4).Any(i=>familyPixels[i*4+3]>0&&(familyPixels[i*4]!=familyPixels[i*4+1]||familyPixels[i*4+1]!=familyPixels[i*4+2])),"family actually colored, not a monochrome pictogram");Check(EmojiColor.Get("🇺🇸")!=null&&EmojiColor.Get("not an emoji")==null&&EmojiColor.Get("❤\ufe0e")==null,"flags/fallback/text presentation");
        composer.Text="";((TextBlock)window.FindName("ComposerHint")).Visibility=Visibility.Visible;((Button)window.FindName("Emoji")).Content=EmojiColor.Glyph("😀",20);window.UpdateLayout();SaveImage(window,Path.Combine(root,"composer-empty.png"));
        composer.Text="😀 👩🏽‍💻 🇺🇸";((TextBlock)window.FindName("ComposerHint")).Visibility=Visibility.Collapsed;EmojiColor.DraftPreview((WrapPanel)window.FindName("EmojiDraftPreview"),composer.Text);window.UpdateLayout();SaveImage(window,Path.Combine(root,"composer.png"));
        var sample=new Window{Title="Color message fixture",Width=620,Height=230,Background=new SolidColorBrush(Color.FromRgb(17,25,32)),Foreground=Brushes.White,Content=new Border{Padding=new Thickness(18),Child=new ChatText{Message="Sent / received / history — same Unicode renderer\n😀 👩🏽‍💻 👨‍👩‍👧‍👦 🇺🇸 1️⃣ ❤️\n日本語 العربية e\u0301",FontSize=18}}};sample.Show();sample.UpdateLayout();SaveImage(sample,Path.Combine(root,"color-chat.png"));sample.Close();
        var boundedUsage=new EmojiUsage(Path.Combine(root,"bounded"),"fixture");foreach(var entry in EmojiCatalog.All.Take(30))boundedUsage.Used(entry.Text);Check(new EmojiUsage(Path.Combine(root,"bounded"),"fixture").Recent.Count==24,"bounded recent restart");File.WriteAllBytes(Path.Combine(root,"bounded","emoji-usage.v1"),new byte[]{1,2,3});Check(new EmojiUsage(Path.Combine(root,"bounded"),"fixture").Recent.Count==0,"corrupt optional preferences isolated");
        string original=String.Join("\n",Corpus);var chat=new ChatText{Message=original};Check(chat.Message==original,"chat exact text");var rendered=(TextBlock)chat.Content;Check(rendered.Inlines.OfType<System.Windows.Documents.InlineUIContainer>().Any(),"chat color images");string reconstructed=String.Concat(rendered.Inlines.Select(inline=>inline is System.Windows.Documents.Run?((System.Windows.Documents.Run)inline).Text:(string)((System.Windows.Documents.InlineUIContainer)inline).Tag));Check(reconstructed==original&&System.Windows.Automation.AutomationProperties.GetName(rendered)==original,"chat exact copy/accessibility identity");
        string longText=String.Concat(Enumerable.Repeat(original,80));var viewer=new BoundedTextView(longText,false,"Long message");Check(viewer.Viewer.Text==longText&&viewer.Viewer.IsReadOnly,"long preview/full source exact");
        var preview=new WrapPanel();var timing=System.Diagnostics.Stopwatch.StartNew();for(int n=0;n<200;n++)EmojiColor.DraftPreview(preview,new string('a',512)+"😀 👩🏽‍💻 🇺🇸");timing.Stop();Check(preview.Children.Count==3,"live colored draft preview");EmojiColor.DraftPreview(preview,String.Concat(Enumerable.Repeat("😀",3000)));Check(preview.Children.Count==24,"bounded large draft preview");Console.WriteLine("DRAFT_PREVIEW 200 in-memory projection updates elapsed_ms="+timing.ElapsedMilliseconds+" cache="+EmojiColor.CachedCount+" (not physical input latency)");
        window.Close();Console.WriteLine("PASS: full catalog color pixels/frozen bounded cache, 100 consecutive selections, favorites star/unstar/restart/profile/scroll isolation, keyboard and outside dismissal, exact editing/undo, protected usage and Unicode long views. Physical acceptance pending.");return 0;
    }catch(Exception e){Console.Error.WriteLine(e.ToString());return 1;}}
}
